// docs/config.js is generated by "Web Form > 2) Build web page". It is PUBLIC – it must only contain
// hashes, never vendor names or access codes.
import test from 'node:test';
import assert from 'node:assert/strict';
import { read, loadConfig } from './helpers.mjs';

const CONFIG = loadConfig();
const gs = read('apps-script/vendor-sheet/Backend_Setup.gs');
const keys = new Function(gs.match(/const WEB_FIELDS = \[[\s\S]*?\];/)[0] + '\nreturn WEB_FIELDS;')().map(f => f[0]);
const isPlaceholder = CONFIG.formAction === '';

test('config has the expected shape', () => {
  for (const k of ['formAction', 'entry', 'facilities', 'salt', 'iterations', 'hashes', 'builtAt']) assert.ok(k in CONFIG, `missing ${k}`);
  assert.equal(CONFIG.iterations, Number(gs.match(/ITERATIONS:\s*(\d+)/)[1]), 'iterations must match Backend_Setup.gs');
  assert.ok(Array.isArray(CONFIG.facilities) && CONFIG.facilities.length > 0, 'no facilities');
  assert.ok(CONFIG.facilities.every(f => !/\(BM\)\s*$/i.test(f)), 'facility names must not carry "(BM)" – nationality is a separate field');
});

test('config is a real build (skipped while docs/config.js is the placeholder)', { skip: isPlaceholder }, () => {
  assert.match(CONFIG.formAction, /^https:\/\/docs\.google\.com\/forms\/d\/e\/[\w-]+\/formResponse$/);
  for (const k of keys) assert.match(CONFIG.entry[k] || '', /^entry\.\d+$/, `entry.${k}`);
  assert.ok(CONFIG.hashes.length > 0, 'no vendor hashes – every vendor needs an access code');
});

test('config never contains plain vendor names or codes', () => {
  assert.ok(CONFIG.hashes.every(h => /^[0-9a-f]{64}$/.test(h)), 'hashes must be 64-char hex');
  const extra = Object.keys(CONFIG).filter(k => !['formAction', 'entry', 'facilities', 'salt', 'iterations', 'hashes', 'builtAt'].includes(k));
  assert.deepEqual(extra, [], 'unexpected keys in config.js: ' + extra.join(', '));
});
